import React from 'react';

const QuestionCard = ({ index, entryData, optionsList, isMasked, onFieldUpdate }) => {
  const hasMismatchError = entryData.confirmedAnswer && (entryData.userAnswer !== entryData.confirmedAnswer);
  const inputType = isMasked ? "password" : "text";

  return (
    <div className="question-entry-container">
      <label className="field-label">Security Step {index + 1}</label>
      
      <select
        className="dropdown-selector"
        value={entryData.selectedQuestionText}
        onChange={e => onFieldUpdate(index, 'selectedQuestionText', e.target.value)}
      >
        <option value="">-- Choose a specific question --</option>
        {optionsList.map((item) => (
          <option key={item.q_id} value={item.question}>
            {item.question}
          </option>
        ))}
      </select>

      <div className="dual-input-wrapper">
        <div className="input-field-box">
          <input
            className="standard-input"
            type={inputType}
            placeholder="Provide Answer"
            value={entryData.userAnswer}
            onChange={e => onFieldUpdate(index, 'userAnswer', e.target.value)}
          />
        </div>
        
        <div className="input-field-box">
          <input
            className={`standard-input ${hasMismatchError ? 'border-error' : ''}`}
            type={inputType}
            placeholder="Confirm Provided Answer"
            value={entryData.confirmedAnswer}
            onChange={e => onFieldUpdate(index, 'confirmedAnswer', e.target.value)}
          />
        </div>
      </div>
      
      {hasMismatchError && <span className="error-message-alert">* Entries do not match</span>}
    </div>
  );
};

export default QuestionCard;
